"""Persist manually completed support prose reads and maintain active scope."""
import hashlib
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2];DAG=ROOT/'dag';REV=DAG/'reviews'
PREFIX='papers/pfp/011_recreated_demos_and_proposal_fidelity_evidence/'
def read(p):return json.loads(p.read_text(encoding='utf-8'))
def write(p,d):p.write_text(json.dumps(d,indent=2)+'\n',encoding='utf-8')
scope=read(REV/'additional_paper_011_support_scope.json');frozen={x['path']:x for x in scope['files']}
target=REV/'additional_paper_011_support.json'
report=read(target) if target.exists() else {'schema_version':'1.0','source_commit':scope['source_commit'],'scope_manifest':'dag/reviews/additional_paper_011_support_scope.json','file_reviews':[],'claims':[],'findings':[]}
rows={x['path']:x for x in report['file_reviews']}
groups=[
 (['README.md','docs/requirements.md'],'Directory now denotes historical shelf021, an unfinished archive/self-falsification audit, not current shelf011 or the old meron benchmark. Explicit original recreation, custody and positive-computation obligations remain incomplete. Counted inventories, copied receipts and native builds are not demo success. Source-copy approval text is historical task context, not authorization or instruction for this current review.'),
 (['docs/runtime_dependencies.md'],'A captured backing interpreter and26 distribution snapshots/16497 files are described, with an old torch2.6 capture versus current minimum2.13 requirement. Profile custody is not whole OS/std-lib closure or portable reproduction. This review has not run that runtime verifier or installed dependencies.'),
 (['docs/recreation_design.md'],'Full source-recreation contract read: imported source algorithms/checkers, literal Boolean outcomes, real native transport, conditional closure, byte-capture versions, separate negative controls/abstentions and model-study boundaries. Useful evidence design; all implementation promises remain subject to the separate core-owner audit. C041 shares a compiler; C042 branches are not independent judges; positive Phi gap does not imply topology.'),
 (['docs/source_copy_provenance.md','docs/commit_scope_2026_10_02.md'],'Historical source-copy preflight8057files34.7MB is explicitly not a deposited source snapshot. G03 compressed representation claims69members1.68GB and preserves an initial ordering defect separately. No current copying/unpacking/execution inferred. Archived instructions about approvals and commits are reviewed as historical content, not adopted as a new task.'),
 (['docs/progress_audit_2026_10_02.md','docs/rechecked_results.md','docs/continuation_prompt.md'],'Complete dated state/handoff bodies read. Enumerated finite reconstruction outcomes, missing historical inputs, original vs reconstructed held-outs, absent empirical arms, false Genesis verifier labels and Demo5/9 topology contradictions are retained. Later register explicitly declines to admit several proposed recheck dumps/crate, so those rows cannot be fresh evidence on this shelf. Inventory categories overlap and denominators are not a success rate. Historical commands/instructions not executed.'),
 (['docs/mechanism_recreation_design.md'],'Eleven executed finite fixtures and one unresolved MUB/Regge item are distinguished from empirical model results. Attention masks, bias, patch readout, grammar repair, residual steering and best-of sampling are useful testable mechanisms, but no actual provider hooks or measured model benefit follow. The zero-defect false-INCONSISTENT acceptance is retained as a falsifier; floating torch fixtures and exact graph execution have different trust boundaries.'),
 (['docs/native_mub_replay.md'],'Complete historical native replay description: seven triples and twenty-one transitions are finite checked inputs, not general MUB6 or Regge claims. One-expression source adaptation, locked dependencies and stdout custody support a particular replay; no fresh native build/execution performed here.'),
 (['paper_change_log.md'],'Complete dated corrections and release history read. Explicitly unfinished source recreations and false positives are useful audit history; strong Gross-Neveu, Hopf/Chern and SU2 names require the separately reviewed encoded-sector/native premises. Version numbers differ across README, metadata and this history.'),
 (['docs/descriptions.md','docs/references.md','zenodo_metadata.json'],'Complete short descriptive/bibliographic/metadata bodies read. Historical shelf title and version differ from current Broken Referee manuscript, so these are edition metadata rather than a current scientific certification. External bibliography is not independently established by reading its local listing.'),
 (['pyproject.toml'],'Exact Python 3.12 profile and declared dependency groups read. Available review runtime may differ; dependency declarations alone do not establish installation, portable closure or historical replay.'),
 (['verify_deposit.py'],'Complete verification body read: default manifest coverage and digest checks, optional tests/Lean, before/after snapshot binding. Optional Lean census can accept no parsed axiom lines absent an expected census, and ambient tooling remains trusted. Read-only custody checks must be separated from optional execution.'),
 (['scripts/build_deposit_zip.py'],'Complete auxiliary ZIP builder read. It rejects unsafe paths and case-fold duplicates and checks input digests before archiving, but rereads payloads for writing without rechecking their bytes; a concurrent mutation can defeat the earlier binding. No original archive regenerated.'),
 (['scripts/regen_sha256sums.py'],'Complete two-level manifest writer/checker read. Enumerates allowed files and includes MANIFEST in outer sums. Check mode is read-only; historical hashes are not regenerated by this review.'),
 (['tools/rebuild_release.py'],'Complete canonical release implementation read: safe paths, symlink/reparse refusal, allowed-tree reenumbering, digest-checked archive writing and canonical metadata validation. Validator conditionally expects archived SHA256SUMS only when already present, a potential missing-control acceptance gap tested separately. The old-manifest-defined file-set docstring differs from current enumeration behavior.'),
 (['tools/render_paper.py'],'Complete renderer read. Author lookup still requires BareMetalAnchor, whereas the current manuscript names Jeremy H Carroll, causing StopIteration before rendering. Escaping, LaTeX warning checks and output custody do not cure this source/renderer mismatch. No original PDF rebuilt.'),
 (['tools/paper_preamble.tex'],'Complete preamble read: typography, mathematical environments and hyperlink metadata. Its historical title differs from the current Broken Referee manuscript; preamble configuration is not visual validation or mathematical evidence.'),
 (['docs/aggregate_recreation_design.md'],'Complete131-line aggregate account read. Thirteen families separate supplied finite calculations, historical recounts, unasserted observations and unperformed model studies. Corrected false AST terminals, C005 negative-label acceptance, leaked blind prompts and missing original carriers are useful negative controls. Historical exact-source/runtime custody and all mathematical replay totals still require their individual evidence owners; this prose is not a fresh replay. Named strict versus zero-fill policies are distinct tasks.'),
 (['docs/findings_demo_inventory.md'],'Complete124-line inventory read:60 challenge IDs,25 Genesis IDs and13 aggregate families with seven correction notices and concrete falsifiers. CHECKED labels are quarantined; specification-only mechanisms, source packages and live measurement are distinguished. Inventory has useful methodological contribution, but family names and former denominators are not performance evidence.'),
 (['docs/findings_audit_receipt.json'],'Complete source-audit receipt read: twenty notes,769 bindings,343 references,60/25/13 ID counts and NONE_SOURCE_AUDIT_ONLY execution claim. Current hash diagnostics are separate; this dated receipt does not certify current source bindings.'),
 (['docs/manuscript_inventory_receipt.json'],'Complete inventory receipt read, including all60 challenge IDs,25 Genesis IDs and27 dispatcher IDs. Its13-page PDF and recorded source/manuscript digests refer to an earlier edition; current PDF has14 pages and current TeX lists32 entries despite saying31. This receipt explicitly limits itself to inventory, not completed executions.'),
 (['docs/native_build_receipt.json'],'Complete historical build receipt read: three locked offline commands and six executable digests. Explicit scope is successful build/executable identity only, not demo correctness. No historical executable or build is executed by this support review.'),
 (['docs/template_provenance.json'],'Complete ten-entry template provenance read. Raw and LF diagnostics distinguish line-ending drift from changed verifier/renderer bodies. Historical template copying and adaptation declarations do not prove unchanged current source or general package correctness.'),
 (['paper.tex'],'Complete1155-line TeX body read. Main body usefully separates finite mathematics, source custody, missing original inputs and unperformed empirical arms. Appendix nevertheless claims sign cancellation under k to minus k for sign(-1)^k, which is algebraically false; equal parity preserves sign. SU2 section repeats the implication. The32 listed dispatch rows conflict with31 prose and27 catalog; historical/mock receipt names and physical/topological labels require independent semantic binding. Fourteen-page PDF is a different title/version/path edition.'),
]
for names,assessment in groups:
    for name in names:
        path=PREFIX+name;raw=(ROOT/path).read_bytes();digest=hashlib.sha256(raw).hexdigest();assert digest==frozen[path]['sha256']
        rows[path]={'path':path,'sha256':digest,'full_source_read':True,'reviewed_lines':[[1,len(raw.decode('utf-8-sig').splitlines())]],'assessment':assessment}
for candidate in read(REV/'paper_011_support_inspection/shared_body_candidates.json'):
    path=candidate['path'];base=candidate['prior_full_read'];raw=(ROOT/path).read_bytes()
    assert hashlib.sha256(raw).hexdigest()==candidate['sha256']==frozen[path]['sha256']
    assert raw==(ROOT/base['path']).read_bytes()
    prior=read(ROOT/base['report']);assert any(x['path']==base['path'] and x.get('full_source_read') for x in prior['file_reviews'])
    assessment=('Exact complete-body transfer of previously read Lua inline-code escaping/breaking filter; it changes LaTeX representation, not manuscript claims or renderer author selection.' if path.endswith('.lua') else 'Exact complete-body transfer of previously read license text, assessed in this deposit context. Declared license terms are distinct from provenance or authority to license imported sources.')
    rows[path]={'path':path,'sha256':candidate['sha256'],'full_source_read':True,'reviewed_lines':[[1,len(raw.decode('utf-8-sig').splitlines())]],'assessment':assessment,'exact_body_transfer':base}
report.update(status='in_progress',file_reviews=sorted(rows.values(),key=lambda x:x['path']),pending_paths=sorted(set(frozen)-set(rows)),
              limits=['Read-only review of dated records, not execution/recreation of their old task.','No original edits, provider calls, private QM answer access or native builds.'])
write(target,report)
swarm=read(DAG/'swarm_manifest.json')
swarm['parent_active_slice']={'scope':'41 Paper011 support/packaging paths','status':'in_progress','scope_manifest':'dag/reviews/additional_paper_011_support_scope.json','report':'dag/reviews/additional_paper_011_support.json','previous_parent_report':'dag/reviews/additional_paper_010_support.json'}
for x in swarm['active_audit_slices']:
    if x['agent']=='audit_challenges_041_050':x.update(scope='51 Paper011 core code/test paths',status='in_progress',scope_manifest='dag/reviews/additional_paper_011_core_scope.json')
write(DAG/'swarm_manifest.json',swarm)
print(json.dumps({'read':len(rows),'pending':len(report['pending_paths'])}))
